// quiz.hpp: practice questions for the AWS Certified AI Practitioner exam (AIF-C01).
// Walk up to a pedestrian and press Enter; they ask one of these at random.
// Covers the five exam domains: AI/ML fundamentals, generative AI fundamentals,
// applications of foundation models, responsible AI, and security/governance.
// Plain ASCII only: raylib's default font has no curly quotes or dashes.
#pragma once

struct QuizQ {
    const char* domain;
    const char* q;
    const char* opts[4];
    int answer;          // index into opts
    const char* why;
};

